<script setup lang="ts">import{Head,useForm,usePage}from'@inertiajs/vue3';import InventoryNav from'../../Components/Common/InventoryNav.vue';interface Item{id:number;code:string;name:string;type:string;bank_name:string|null;account_number:string|null;active:boolean;ledger_code:string;ledger_name:string;balance:string}interface Ledger{id:number;code:string;name:string}defineProps<{accounts:Item[];ledgerAccounts:Ledger[]}>();const page=usePage<{flash?:{success?:string}}>();const form=useForm({code:'',name:'',type:'cash',accounting_account_id:'',bank_name:'',account_number:''});const save=()=>form.post('/accounting/treasury',{onSuccess:()=>form.reset()});const money=(v:string)=>new Intl.NumberFormat('es-HN',{style:'currency',currency:'HNL'}).format(Number(v));</script>
<template><Head title="Caja y bancos"/><main class="page"><InventoryNav/><p class="eyebrow">TESORERÍA</p><h1>Caja y cuentas bancarias</h1><p>Los saldos se calculan desde las partidas contables publicadas.</p><p v-if="page.props.flash?.success" class="success">{{page.props.flash.success}}</p><div class="layout"><form class="card form" @submit.prevent="save"><h2>Nueva cuenta de tesorería</h2><label>Código *<input v-model="form.code" required></label><label>Nombre *<input v-model="form.name" required></label><label>Tipo<select v-model="form.type"><option value="cash">Caja</option><option value="bank">Banco</option><option value="wallet">Billetera/POS</option></select></label><label>Cuenta contable *<select v-model="form.accounting_account_id" required><option value="">Selecciona</option><option v-for="a in ledgerAccounts" :key="a.id" :value="a.id">{{a.code}} — {{a.name}}</option></select></label><label>Banco<input v-model="form.bank_name"></label><label>Número de cuenta<input v-model="form.account_number"></label><p class="error">{{Object.values(form.errors)[0]}}</p><button :disabled="form.processing">Guardar cuenta</button></form><section class="card table"><h2>Saldos actuales</h2><table><thead><tr><th>Código</th><th>Cuenta</th><th>Tipo</th><th>Cuenta contable</th><th class="right">Saldo</th></tr></thead><tbody><tr v-for="a in accounts" :key="a.id"><td>{{a.code}}</td><td><strong>{{a.name}}</strong><small>{{a.bank_name||''}} {{a.account_number||''}}</small></td><td>{{a.type}}</td><td>{{a.ledger_code}} — {{a.ledger_name}}</td><td class="right">{{money(a.balance)}}</td></tr><tr v-if="!accounts.length"><td colspan="5">No hay cuentas configuradas.</td></tr></tbody></table></section></div></main></template>
<style scoped>.page{max-width:1500px;margin:auto;padding:2rem}.eyebrow{color:var(--p-primary-color);font-weight:800;font-size:.75rem;letter-spacing:.15em}.layout{display:grid;grid-template-columns:minmax(18rem,.7fr) minmax(0,1.3fr);gap:1rem}.card{padding:1.5rem;border:1px solid var(--p-content-border-color);border-radius:1rem;background:var(--p-content-background);margin-top:1rem}.form{display:grid;gap:.8rem}.form label{display:grid;gap:.35rem;font-weight:600}input,select{padding:.7rem;border:1px solid var(--p-content-border-color);border-radius:.5rem;background:transparent;color:inherit}button{padding:.75rem;border:0;border-radius:.55rem;background:var(--p-primary-color);color:var(--p-primary-contrast-color);font-weight:700}.table{overflow:auto}table{width:100%;border-collapse:collapse}td,th{padding:.8rem;border-bottom:1px solid var(--p-content-border-color);text-align:left}small{display:block;color:var(--p-text-muted-color)}.right{text-align:right}.success{padding:.75rem;background:#dcfce7;color:#166534;border-radius:.5rem}.error{color:#dc2626}@media(max-width:900px){.layout{grid-template-columns:1fr}.page{padding:1rem}}</style>
